Robot Control Service Protocol Buffer<pre><code>service RobotControl {
    rpc GetStatus(StatusRequest) returns (StatusResponse);
    rpc Move(MoveRequest) returns (MoveResponse);
    rpc EmergencyStop(EmptyRequest) returns (StatusResponse);
    rpc GetPose(EmptyRequest) returns (PoseResponse);
}

message MoveRequest {
    float linear_x = 1;
    float linear_y = 2;
    float angular_z = 3;
    float duration = 4;
}
